import {SHADERS,VIEWS,objectLabel} from './config.js';
import {LIGHT_GROUPS} from './lighting.js';
const paths={left:'m14 5-7 7 7 7',right:'m10 5 7 7-7 7',home:'M3 10 12 3l9 7v10H3Z M9 20v-6h6v6',workspace:'M2 5h8v9H2z M14 5h8v9h-8z M6 14v4m-3 0h6m9-4v4m-3 0h6',lounge:'M5 9V6a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v3 M3 9h3v6h12V9h3v11H3Z M6 20v1m12-1v1',project:'M3 17 17 3l4 4L7 21Z M13 7l3 3m-6 0 3 3m-6 0 3 3',coffee:'M4 5h12v11a3 3 0 0 1-3 3H7a3 3 0 0 1-3-3Z M16 7h2a3 3 0 0 1 0 6h-2 M2 22h17',light:'M9 18h6m-5 3h4 M8 14a6 6 0 1 1 8 0l-1 3H9Z',moon:'M20 15a8 8 0 0 1-11-11 8 8 0 1 0 11 11Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',magic:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z M21 2v4m-2-2h4',close:'m6 6 12 12M6 18 18 6',pause:'M9 5v14M15 5v14',play:'m8 5 11 7-11 7Z'};
export const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]}"/></svg>`;
export function setupUI(actions){
 const $=id=>document.getElementById(id),views=$('views'),caption=$('shot-caption');let current=0,lastCaption=-2,wasTraveling=false,scrambleToken=0,fxPending=false;
 const panels=[['view-panel','views-toggle'],['light-panel','lights'],['shader-panel','shaders']];
 function showPanel(id){for(const[panel,button]of panels){const active=panel===id&&$(panel).hidden;$(panel).hidden=!active;$(button).setAttribute('aria-expanded',String(active));}document.body.classList.toggle('panel-open',panels.some(([panel])=>!$(panel).hidden));}
 function chooseView(i){current=(i+VIEWS.length)%VIEWS.length;showPanel(null);actions.view(current);}
 VIEWS.forEach((v,i)=>{const b=document.createElement('button');b.setAttribute('aria-label',i===2||i===3?v.title:v.name);b.setAttribute('aria-pressed',String(i===0));b.innerHTML=`<small>${String(i).padStart(2,'0')}</small><span>${i===2||i===3?'Workstation '+v.name:v.name}</span>`;b.onclick=()=>chooseView(i);views.append(b);});
 $('views-toggle').onclick=()=>showPanel('view-panel');$('previous-view').innerHTML=icon('left');$('previous-view').onclick=()=>chooseView(current-1);$('next-view').innerHTML=icon('right');$('next-view').onclick=()=>chooseView(current+1);
 $('lights').innerHTML=icon('light');$('shaders').innerHTML=icon('magic')+'<span>Carbone vivo</span>';$('day').innerHTML=icon('moon')+'<span>Notte</span>';$('lights').onclick=()=>showPanel('light-panel');$('shaders').onclick=()=>showPanel('shader-panel');
 document.querySelectorAll('.close-panel').forEach(b=>{b.innerHTML=icon('close');b.onclick=()=>showPanel(null);});
 for(const[id,label]of LIGHT_GROUPS){const b=document.createElement('button');b.className='light-option';b.dataset.light=id;b.setAttribute('aria-pressed','true');b.innerHTML=`<span>${label}</span><i class="switch" aria-hidden="true"></i>`;b.onclick=()=>actions.light(id);$('light-options').append(b);}
 for(const s of SHADERS){const b=document.createElement('button');b.className='shader-option';b.dataset.shader=s.id;b.style.setProperty('--fx',s.accent);b.setAttribute('aria-pressed',String(s.id===0));b.setAttribute('aria-label',s.name+' — '+s.detail);b.innerHTML=`<span class="fx-number">${String(s.id+1).padStart(2,'0')}</span><span class="fx-name">${s.name}</span><span class="fx-detail">${s.detail}</span>`;b.onclick=()=>{actions.shader(s.id);showPanel(null);};$('shader-options').append(b);}
 $('day').onclick=()=>actions.day();$('motion').innerHTML=icon('pause');$('motion').onclick=()=>actions.motion();$('enter').onclick=()=>chooseView(1);$('exit').onclick=()=>{showPanel(null);actions.exit();};$('focus-close').innerHTML=icon('close');$('focus-close').onclick=()=>actions.unfocus();$('retry').onclick=()=>location.reload();
 for(let i=0;i<14;i++){const fragment=document.createElement('i');fragment.style.setProperty('--i',i);document.querySelector('.caption-fragments').append(fragment);}
 function revealCaption(index){const view=VIEWS[index]||{title:'Segui la tua curiosità.',copy:'Esplora lo spazio, avvicinati ai dettagli.',id:'free'};caption.classList.remove('reveal');$('shot-title').replaceChildren();view.title.split(' ').forEach((word,i)=>{const span=document.createElement('span');span.className='word';span.style.setProperty('--word',i);span.textContent=word+' ';$('shot-title').append(span);});$('shot-copy').textContent=view.copy;const label=(index>=0?String(index).padStart(2,'0'):'↗')+' / '+(index===0?'MEMENTO STUDIO':index<0?'ESPLORAZIONE LIBERA':VIEWS[index].name.toUpperCase());$('shot-index').textContent=label;
 const token=++scrambleToken,start=performance.now();if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.body.classList.contains('paused')){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789';const animate=now=>{if(token!==scrambleToken)return;const progress=Math.min(1,(now-start)/640);$('shot-index').textContent=[...label].map((c,i)=>c===' '||i/label.length<progress?c:chars[(Math.floor(now/58)+i*7)%chars.length]).join('');if(progress<1)requestAnimationFrame(animate);};requestAnimationFrame(animate);}
 requestAnimationFrame(()=>{caption.classList.add('reveal');caption.classList.remove('traveling');});lastCaption=index;
 }
 document.addEventListener('pointerdown',e=>{if(!e.target.closest('.dock'))showPanel(null);});document.addEventListener('keydown',e=>{if(e.code==='Escape'){const open=panels.some(([id])=>!$(id).hidden);showPanel(null);if(!open)actions.escape();}});
 document.addEventListener('pointermove',e=>{document.querySelectorAll('.cut-surface,.cut-button').forEach(el=>{const r=el.getBoundingClientRect();if(e.clientX>r.left-150&&e.clientX<r.right+150&&e.clientY>r.top-150&&e.clientY<r.bottom+150){el.style.setProperty('--mx',`${e.clientX-r.left}px`);el.style.setProperty('--my',`${e.clientY-r.top}px`);}});},{passive:true});
 return{
 fxBusy(busy){if(fxPending!==busy){fxPending=busy;$('shaders').setAttribute('aria-busy',String(busy));}},
 progress(v){$('load-percent').textContent=`${Math.round(v*100)}%`;$('load-bar').style.width=`${v*100}%`;},ready(){this.progress(1);$('controls').hidden=false;document.body.classList.add('ready');},error(message){$('error-message').textContent=message;$('error').hidden=false;$('loading').hidden=true;},
 navigation(nav){const inside=nav.state!=='exterior';document.querySelector('.entry').inert=inside||!!nav.focus;document.querySelector('.entry').setAttribute('aria-hidden',String(inside||!!nav.focus));$('exit').hidden=!inside;document.body.classList.toggle('inside',inside);[...views.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===nav.view)));if(nav.view>=0){current=nav.view;$('view-current').textContent=current===0?'Inquadrature':VIEWS[current].name;}else $('view-current').textContent='Esplora';
 const traveling=!!nav.transition&&!nav.focus;if(traveling){caption.classList.add('traveling');wasTraveling=true;}else if(wasTraveling||nav.view!==lastCaption){wasTraveling=false;revealCaption(nav.view);}},
 focus(object){document.body.classList.toggle('focused',!!object);$('focus-card').hidden=!object;if(object)$('focus-name').textContent=objectLabel(object.name);},
 lights(groups){document.querySelectorAll('[data-light]').forEach(b=>b.setAttribute('aria-pressed',String(!!groups[b.dataset.light].target)));},
 shader(id){document.querySelectorAll('[data-shader]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.shader)===id)));$('shaders').innerHTML=icon('magic')+`<span>${SHADERS[id].name}</span>`;$('status').textContent=SHADERS[id].name+'. '+SHADERS[id].detail;},
 day(day){$('day').setAttribute('aria-label',day?'Attiva notte':'Attiva giorno');$('day').setAttribute('aria-pressed',String(day));$('day').innerHTML=icon(day?'sun':'moon')+`<span>${day?'Giorno':'Notte'}</span>`;document.body.classList.toggle('day',day);},
 motion(paused){document.body.classList.toggle('paused',paused);$('motion').setAttribute('aria-pressed',String(paused));$('motion').setAttribute('aria-label',paused?'Riprendi le animazioni':'Metti in pausa le animazioni');$('motion').innerHTML=icon(paused?'play':'pause');},announce(message){$('status').textContent=message;}
 };
}
